editorial:
Keep candidate indices in increasing index order. For minima, pop larger or equal values from the back, since the new value is no larger and expires later. For maxima do the opposite. Remove expired indices from the front; the remaining fronts are the extrema. Time O(n), space O(k) besides input or output storage.
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,k; cin>>n>>k;
    deque<pair<int,int>> low,high;
    for (int i=0;i<n;++i) {
        int x; cin>>x;
        if (!low.empty() && low.front().first<=i-k) low.pop_front();
        if (!high.empty() && high.front().first<=i-k) high.pop_front();
        while (!low.empty() && low.back().second>=x) low.pop_back();
        while (!high.empty() && high.back().second<=x) high.pop_back();
        low.emplace_back(i,x);
        high.emplace_back(i,x);
        if (i>=k-1) cout<<low.front().second<<' '<<high.front().second<<'\n';
    }
}
